<?php
namespace ScratchByPHP\Sb3;
use ScratchByPHP\Analysis\ProjectAnalyzer;
final class Sb3Archive { private ?string $temp=null; public function __construct(private string $path){} public static function open(string $path):self{if(!is_file($path))throw new \InvalidArgumentException('SB3 dosyası bulunamadı.');return new self($path);} public function projectJson():array{$raw=file_get_contents($this->path);if($raw!==false&&str_starts_with(ltrim($raw),'{')){$d=json_decode($raw,true);if(is_array($d))return $d;}if(!class_exists('ZipArchive'))throw new \RuntimeException('Gerçek .sb3 için ext-zip gerekli.');$z=new \ZipArchive();if($z->open($this->path)!==true)throw new \RuntimeException('SB3 açılamadı.');$raw=$z->getFromName('project.json');$z->close();$d=json_decode((string)$raw,true);if(!is_array($d))throw new \RuntimeException('project.json geçersiz.');return $d;} public function analyze():ProjectAnalyzer{return ProjectAnalyzer::fromJson($this->projectJson());} public function assets():array{$j=$this->projectJson();$out=[];foreach($j['targets']??[] as $t){foreach($t['costumes']??[] as $a)$out[]=$a;foreach($t['sounds']??[] as $a)$out[]=$a;}return $out;} public function extract(string $dir):string{if(!class_exists('ZipArchive'))throw new \RuntimeException('ext-zip gerekli.');$z=new \ZipArchive();if($z->open($this->path)!==true)throw new \RuntimeException('SB3 açılamadı.');if(!is_dir($dir))mkdir($dir,0775,true);$z->extractTo($dir);$z->close();return $dir;} }
